public interface ProductRepository extends JpaRepository<Product, UUID> {

    @Modifying
    @Query("UPDATE Product p SET p.stock = p.stock + :units WHERE p.id = :id")
    int addStock(@Param("id") UUID id, @Param("units") int units);

    @Modifying
    @Query("UPDATE Product p SET p.stock = p.stock - :q WHERE p.id = :id AND p.stock >= :q")
    int reserveStock(@Param("id") UUID id, @Param("q") int q);

    @Modifying
    @Query("UPDATE Product p SET p.stock = p.stock + :q WHERE p.id = :id")
    int releaseStock(@Param("id") UUID id, @Param("q") int q);
}

package com.study.app.command;

import com.study.app.domain.Product;
import com.study.app.domain.ProductRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.util.UUID;

@Service
public class ProductCommandService {

    private final ProductRepository products;

    public ProductCommandService(ProductRepository products) {
        this.products = products;
    }

    @Transactional
    public Product create(String name, int unitPrice, int stock) {
        return products.save(new Product(name, unitPrice, stock));
    }

    @Transactional
    public void restock(UUID id, int units) {
        if (!products.existsById(id)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "product not found");
        }
        products.addStock(id, units);
    }

    @Transactional
    public boolean reserve(UUID productId, int quantity) {
        return products.reserveStock(productId, quantity) > 0;
    }

    @Transactional
    public void release(UUID productId, int quantity) {
        products.releaseStock(productId, quantity);
    }
}

package com.study.app.web;

import com.study.app.command.ProductCommandService;
import com.study.app.domain.Product;
import com.study.app.domain.ProductRepository;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.UUID;

@RestController
public class ProductController {

    private final ProductCommandService commandService;
    private final ProductRepository products;

    public ProductController(ProductCommandService commandService, ProductRepository products) {
        this.commandService = commandService;
        this.products = products;
    }

    record CreateProductRequest(
        @NotBlank String name,
        @NotNull @Min(1) Integer unitPrice,
        @NotNull @Min(0) Integer stock
    ) {}

    record RestockRequest(@NotNull @Min(1) Integer units) {}

    record ProductView(UUID id, String name, int unitPrice, int stock) {}

    @PostMapping("/products")
    @ResponseStatus(HttpStatus.CREATED)
    public ProductView create(@RequestBody @Valid CreateProductRequest req) {
        Product p = commandService.create(req.name(), req.unitPrice(), req.stock());
        return new ProductView(p.getId(), p.getName(), p.getUnitPrice(), p.getStock());
    }

    @GetMapping("/products/{id}")
    public ProductView get(@PathVariable UUID id) {
        return products.findById(id)
            .map(p -> new ProductView(p.getId(), p.getName(), p.getUnitPrice(), p.getStock()))
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "product not found"));
    }

    @PostMapping("/products/{id}/restock")
    @ResponseStatus(HttpStatus.ACCEPTED)
    public void restock(@PathVariable UUID id, @RequestBody @Valid RestockRequest req) {
        commandService.restock(id, req.units());
    }
}

