package com.study.app.web;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientResponseException;
import java.util.UUID;

@RestController
public class EdgeController {

    private final RestClient ordersClient;
    private final RestClient inventoryClient;
    private final RestClient customersClient;

    public EdgeController(
            @Qualifier("ordersClient") RestClient ordersClient,
            @Qualifier("inventoryClient") RestClient inventoryClient,
            @Qualifier("customersClient") RestClient customersClient) {
        this.ordersClient = ordersClient;
        this.inventoryClient = inventoryClient;
        this.customersClient = customersClient;
    }

    // ---- Products (inventory) ----

    @PostMapping("/products")
    public ResponseEntity<byte[]> createProduct(@RequestBody byte[] body) {
        return proxy(inventoryClient, HttpMethod.POST, "/products", body);
    }

    @GetMapping("/products/{id}")
    public ResponseEntity<byte[]> getProduct(@PathVariable String id) {
        return proxy(inventoryClient, HttpMethod.GET, "/products/" + id, null);
    }

    @PostMapping("/products/{id}/restock")
    public ResponseEntity<byte[]> restockProduct(@PathVariable String id, @RequestBody byte[] body) {
        return proxy(inventoryClient, HttpMethod.POST, "/products/" + id + "/restock", body);
    }

    // ---- Customers ----

    @PostMapping("/customers")
    public ResponseEntity<byte[]> createCustomer(@RequestBody byte[] body) {
        return proxy(customersClient, HttpMethod.POST, "/customers", body);
    }

    @GetMapping("/customers/{id}")
    public ResponseEntity<byte[]> getCustomer(@PathVariable String id) {
        return proxy(customersClient, HttpMethod.GET, "/customers/" + id, null);
    }

    @PostMapping("/customers/{id}/deposit")
    public ResponseEntity<byte[]> deposit(@PathVariable String id, @RequestBody byte[] body) {
        return proxy(customersClient, HttpMethod.POST, "/customers/" + id + "/deposit", body);
    }

    @GetMapping("/customers/{id}/notifications")
    public ResponseEntity<byte[]> notifications(@PathVariable String id) {
        return proxy(customersClient, HttpMethod.GET, "/customers/" + id + "/notifications", null);
    }

    // ---- Orders ----

    @PostMapping("/orders")
    public ResponseEntity<byte[]> placeOrder(@RequestBody byte[] body) {
        return proxy(ordersClient, HttpMethod.POST, "/orders", body);
    }

    @GetMapping("/orders/{id}")
    public ResponseEntity<byte[]> getOrder(@PathVariable String id) {
        return proxy(ordersClient, HttpMethod.GET, "/orders/" + id, null);
    }

    // ---- Stats ----

    @GetMapping("/stats/orders")
    public ResponseEntity<byte[]> stats() {
        return proxy(ordersClient, HttpMethod.GET, "/stats/orders", null);
    }

    // ---- Generic proxy ----

    private ResponseEntity<byte[]> proxy(RestClient client, HttpMethod method, String path, byte[] body) {
        try {
            var spec = client.method(method).uri(path);
            if (body != null && body.length > 0) {
                spec.contentType(org.springframework.http.MediaType.APPLICATION_JSON).body(body);
            }
            return spec.retrieve()
                .onStatus(status -> true, (req, resp) -> {})
                .toEntity(byte[].class);
        } catch (RestClientResponseException ex) {
            return ResponseEntity.status(ex.getStatusCode())
                .contentType(org.springframework.http.MediaType.APPLICATION_JSON)
                .body(ex.getResponseBodyAsByteArray());
        } catch (Exception ex) {
            return ResponseEntity.status(HttpStatus.BAD_GATEWAY)
                .body(ex.getMessage().getBytes());
        }
    }
}

